export const getFormValue = (formData: FormData, name: string, fallback = "None") => {
  const value = formData.get(name);

  return typeof value === "string" && value.length > 0 ? value : fallback;
};

export const getFormValues = (formData: FormData, name: string) =>
  formData.getAll(name).filter((value): value is string => typeof value === "string");

import { getFormValues } from "../../form/examples/form-value";
import * as React from "react";
import { toast } from "@/registry/erbium/ui/toast";

import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireItem,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/registry/erbium/ui/questionnaire";

const items = [
  {
    choices: [{ value: "source" }, { value: "tests" }, { value: "docs" }, { value: "history" }],
    name: "context",
    required: true,
  },
] as const;

export const QuestionnaireMultiple = () => {
  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    const context = getFormValues(new FormData(event.currentTarget), "context");

    toast.add({
      description: `Context: ${context.join(", ") || "None"}`,
      title: "Context selected",
    });
  };

  return (
    <Questionnaire
      className="mx-auto max-w-md"
      items={items}
      shortcuts="letters"
      onSubmit={handleSubmit}
    >
      <QuestionnaireItem name="context" multiple required>
        <QuestionnaireTitle>What context should the agent inspect?</QuestionnaireTitle>
        <QuestionnaireDescription>
          Select every source that may affect the implementation.
        </QuestionnaireDescription>
        <QuestionnaireChoices>
          <QuestionnaireChoice value="source">Relevant source files</QuestionnaireChoice>
          <QuestionnaireChoice value="tests">Existing tests</QuestionnaireChoice>
          <QuestionnaireChoice value="docs">Architecture documentation</QuestionnaireChoice>
          <QuestionnaireChoice value="history">Recent commit history</QuestionnaireChoice>
        </QuestionnaireChoices>
        <QuestionnaireError />
      </QuestionnaireItem>

      <QuestionnaireActions>
        <QuestionnaireSubmit>Share context</QuestionnaireSubmit>
      </QuestionnaireActions>
    </Questionnaire>
  );
};

import { QuestionnaireMultiple } from "../examples/questionnaire-multiple";

const Example = () => <QuestionnaireMultiple />;

export default Example;
